import { test, expect } from "../helpers/theme-browser";

test("workspace tabs keep one indicator aligned through navigation and resizing", async ({
  page,
}) => {
  await page.emulateMedia({ reducedMotion: "no-preference" });
  await page.goto("/compose");
  const nav = page.getByRole("navigation", { name: "Main navigation" });
  const pill = nav.locator(".workspace-nav-highlight");
  await expect(nav).toHaveAttribute("data-highlight-ready", "");
  // The same DOM element must travel between destinations, including interruptions.
  await pill.evaluate((el) =>
    el.setAttribute("data-motion-test", "persistent"),
  );
  async function expectAligned() {
    await expect
      .poll(async () => {
        return nav.evaluate((el) => {
          const active = el
            .querySelector('[aria-current="page"]')!
            .getBoundingClientRect();
          const highlight = el
            .querySelector(".workspace-nav-highlight")!
            .getBoundingClientRect();
          return Math.max(
            Math.abs(active.left - highlight.left),
            Math.abs(active.top - highlight.top),
            Math.abs(active.width - highlight.width),
            Math.abs(active.height - highlight.height),
          );
        });
      })
      .toBeLessThan(1);
    await expect(pill).toHaveAttribute("data-motion-test", "persistent");
  }
  await expectAligned();
  for (const name of ["Contacts", "Templates", "Usage", "History", "Compose"]) {
    // dispatchEvent permits a new selection while the previous transition is running.
    await nav.getByRole("link", { name, exact: true }).dispatchEvent("click");
    await expect(nav.locator('[aria-current="page"]')).toHaveAttribute(
      "aria-label",
      name,
    );
  }
  await expectAligned();
  for (const width of [390, 768, 1280]) {
    await page.setViewportSize({ width, height: 844 });
    await expectAligned();
    expect(
      await page.evaluate(
        () => document.documentElement.scrollWidth <= innerWidth,
      ),
    ).toBe(true);
  }
  await page.emulateMedia({ reducedMotion: "reduce" });
  await nav.getByRole("link", { name: "Contacts", exact: true }).click();
  await expect(nav.locator('[aria-current="page"]')).toHaveAttribute(
    "aria-label",
    "Contacts",
  );
  await expectAligned();
  expect(
    await pill.evaluate((el) =>
      parseFloat(getComputedStyle(el).transitionDuration),
    ),
  ).toBeLessThan(0.001);
});
